import {LightningElement} from 'lwc'; export default class Probe extends LightningElement {result='pending'; renderedCallback(){if(this.result==='pending'){let e=this.template.querySelector('lightning-rich-text-toolbar-button');this.result=JSON.stringify({show:typeof e.showPopup,close:typeof e.closePopup,selected:e.selected});}} open(){let e=this.template.querySelector('lightning-rich-text-toolbar-button');try {let v=e.showPopup();this.result=JSON.stringify({action:'show',type:typeof v});}catch(x){this.result=JSON.stringify({action:'show',name:x.name,message:x.message});}} close(){let e=this.template.querySelector('lightning-rich-text-toolbar-button');try{let v=e.closePopup();this.result=JSON.stringify({action:'close',type:typeof v});}catch(x){this.result=JSON.stringify({action:'close',name:x.name,message:x.message});}} }